#!/usr/bin/env python3
# Preview only: Casa Leon banner photo, a Costa Rica map with location pins and properties by region to map-nuevo.html (office directions stay below).
import base64
P = '/var/www/propertiesincostarica.com/web/map-nuevo.html'
TOP = base64.b64decode('').decode('utf-8')
CSS = base64.b64decode('').decode('utf-8')
s = open(P, encoding='utf-8', errors='surrogateescape').read()
if 'mp-pcr' in s:
    raise SystemExit('Ya tenia el mapa')
k = '<!-- InstanceBeginEditable name="content" -->'
i = s.index(k) + len(k)
s = s[:i] + '\n' + TOP + '\n' + s[i:]
s = s.replace('</head>', CSS, 1)
import re
IMG = 'https://cdn.propertiesincostarica.com/properties/Images/ocean-setting/opt2/photo-1.jpg'
pic = ('<picture><img src="' + IMG + '" alt="" width="1672" height="941" fetchpriority="high" decoding="async" style="object-fit:cover;object-position:center 55%"></picture>')
s, n = re.subn(r'(<section class="sp-hero"[^>]*>\s*)<picture>.*?</picture>', lambda m: m.group(1) + pic, s, count=1, flags=re.S)
print('Foto de Casa Leon en el banner: ' + ('SI' if n else 'NO'))
open(P, 'w', encoding='utf-8', errors='surrogateescape').write(s)
print('Mapa de Costa Rica con %d ubicaciones agregado' % 23)
print('Vista previa a la vista previa: https://www.propertiesincostarica.com/map-nuevo.html')
print('LISTO')
